package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's claimed-total
 * and due-total. A change takes them before it writes, then {@link #record} audits the ones it moved: a ROLLUP line
 * per person whose figures changed (in the order they were added; a new person counts as changed), then a TOTALS
 * line when the sheet's totals changed.
 */
@Service
public class Rollup {

    /** A person's figures: claimed (two decimals) and due-total (two decimals, or n/a). */
    public record Figures(String name, String claimed, String dueTotal) {
    }

    /** The sheet's figures at one moment: per person id, in the order they were added, and the totals. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
    }

    private final People people;
    private final Claims claims;
    private final Rates rates;
    private final SheetClock clock;
    private final Audit audit;

    public Rollup(People people, Claims claims, Rates rates, SheetClock clock, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.clock = clock;
        this.audit = audit;
    }

    /** The sheet's figures now. */
    public Snapshot take(String sheet) {
        LocalDate today = clock.today(sheet);
        List<Rate> sheetRates = rates.list(sheet);
        List<Claim> counted = claims.list(sheet).stream().filter(Claim::counts).toList();
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.list(sheet)) {
            List<Claim> mine = counted.stream().filter((c) -> c.person() == person.id()).toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            for (Claim claim : mine) {
                claimed = claimed.add(new BigDecimal(claim.amount()));
                BigDecimal d = claim.due(sheetRates, person.grade());
                due = d == null ? due : due.add(d);
            }
            // n/a when the grade has no rate on the sheet's today, unless a claim keeps a figure.
            boolean na = Rate.on(sheetRates, person.grade(), today) == null && mine.stream().noneMatch(Claim::fixed);
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), na ? "n/a" : due.toPlainString()));
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** Audits the figures the change moved since {@code before}, after the change's own lines. */
    public void record(String sheet, String user, Snapshot before) {
        Snapshot after = take(sheet);
        String prefix = " sheet=" + sheet + " by=" + user + " ";
        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
            Figures now = entry.getValue();
            Figures was = before.people().get(entry.getKey());
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
                audit.record("ROLLUP" + prefix + "person=" + now.name() + " claimed=" + now.claimed() + " due-total="
                        + now.dueTotal());
            }
        }
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            audit.record("TOTALS" + prefix + "claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/**
 * A person on a sheet: name (unique on the sheet, ignoring case) and grade (A, B or C). The version
 * is raised by one on every save. The retired-from date (yyyy-mm-dd) is null unless they are retired;
 * once it is set they count as retired, whatever the date.
 */
public record Person(long id, String name, String grade, long version, String retiredFrom) {

    /** Whether a claim dated {@code date} is after this person's retirement, and so refused. */
    public boolean retiredBefore(LocalDate date) {
        return retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom));
    }
}
package net.officefloor.hq.app.person;

import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet. */
@Repository
public class People {

    private static final RowMapper<Person> ROW = (rs, i) -> new Person(rs.getLong("id"), rs.getString("name"),
            rs.getString("grade"), rs.getLong("version"),
            rs.getDate("retired_from") == null ? null : rs.getDate("retired_from").toLocalDate().toString());

    private final JdbcTemplate jdbc;

    public People(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Everyone on the sheet, in the order they were added. */
    public List<Person> list(String sheet) {
        return jdbc.query("SELECT id, name, grade, version, retired_from FROM person WHERE sheet = ? ORDER BY id", ROW, sheet);
    }

    public Person find(String sheet, long id) {
        List<Person> found = jdbc.query("SELECT id, name, grade, version, retired_from FROM person WHERE sheet = ? AND id = ?", ROW,
                sheet, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name, ignoring case; null when there is none. */
    public Person findByName(String sheet, String name) {
        List<Person> found = jdbc.query(
                "SELECT id, name, grade, version, retired_from FROM person WHERE sheet = ? AND name_key = LOWER(?)", ROW, sheet, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether someone on the sheet other than {@code except} has this name, ignoring case. */
    private boolean nameTaken(String sheet, String name, Long except) {
        Integer taken = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
                Integer.class, sheet, name, except, except);
        return taken != null && taken > 0;
    }

    public Person add(String sheet, String name, String grade) throws DuplicatePersonNameException {
        if (nameTaken(sheet, name, null)) {
            throw new DuplicatePersonNameException(name);
        }
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        try {
            insert(sheet, name, grade, keys);
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(name);
        }
        return new Person(keys.getKey().longValue(), name, grade, 0, null);
    }

    private void insert(String sheet, String name, String grade, GeneratedKeyHolder keys) {
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO person (sheet, name, grade) VALUES (?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheet);
            ps.setString(2, name);
            ps.setString(3, grade);
            return ps;
        }, keys);
    }

    /** Retire the person from the date. */
    public void retire(String sheet, long id, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet = ? AND id = ?", Date.valueOf(from), sheet, id);
    }

    /** Save the person over the version it carries, raising the version; refused when it has moved on. */
    public void update(String sheet, Person person) throws DuplicatePersonNameException, StalePersonException {
        if (nameTaken(sheet, person.name(), person.id())) {
            throw new DuplicatePersonNameException(person.name());
        }
        int updated;
        try {
            updated = jdbc.update(
                    "UPDATE person SET name = ?, grade = ?, version = version + 1 WHERE sheet = ? AND id = ? AND version = ?",
                    person.name(), person.grade(), sheet, person.id(), person.version());
        } catch (DuplicateKeyException e) {
            throw new DuplicatePersonNameException(person.name());
        }
        if (updated == 0) {
            throw new StalePersonException(person.id());
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Retires the person from the date: they count as retired at once, and their claims keep counting. */
public class RetirePerson {
    public void retire(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @Val LocalDate from, People people, Audit audit) {
        people.retire(sheet, person.id(), from);
        audit.record("PERSON_RETIRED sheet=" + sheet + " by=" + user + " name=" + person.name() + " from=" + from);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** The date to retire from: the one given, or the sheet's today when blank. */
public class ValidateRetire {
    public void validate(@PathVariable("sheet") String sheet, @RequestBody RetireRequest request, SheetClock clock,
            Out<LocalDate> from) throws InvalidPersonException {
        String date = request == null || request.from() == null ? "" : request.from().trim();
        try {
            from.set(date.isEmpty() ? clock.today(sheet) : LocalDate.parse(date));
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a valid date: " + date);
        }
    }
}
package net.officefloor.hq.app.person;

/** Body of POST /api/sheets/{sheet}/people/{person}/retire: the date retired from (blank for the sheet's today). */
public record RetireRequest(String from) {
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Responds with everyone on the sheet, in the order they were added. */
public class RespondWithPeople {
    public void respond(@PathVariable("sheet") String sheet, People people, ObjectResponse<List<Person>> response) {
        response.send(people.list(sheet));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheet") String sheet, @PathVariable("person") long person, People people,
            Out<Person> loaded) throws PersonNotFoundException {
        Person found = people.find(sheet, person);
        if (found == null) {
            throw new PersonNotFoundException(person);
        }
        loaded.set(found);
    }
}
# Validate before load so a bad date is a 400, not masked by a 404. Responds with the sheet's people.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ transaction ]
