        people.hold(sheet, person.id(), held);
        audit.record((held ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + sheet + " by=" + user + " name="
                + person.name());
        rollup.record(sheet, user, before);
    }
}
